import{_ as i,o as t,c as a,a2 as s}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Get started with CX","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://cx-pl.io/getting-started/"}],["meta",{"property":"og:url","content":"https://cx-pl.io/getting-started/"}]]},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":null}'),l={name:"getting-started/index.md"};function r(n,e,o,d,p,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="get-started-with-cx" tabindex="-1">Get started with CX <a class="header-anchor" href="#get-started-with-cx" aria-label="Permalink to &quot;Get started with CX&quot;">​</a></h1><p>CX is an experimental language and compiler. This guide builds the compiler from source and runs a small program. The compiler emits C and CMake build files; compiling and running the result also requires a native C toolchain.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>.NET 10 SDK to build the compiler.</li><li>CMake and a native compiler supported by the selected platform.</li><li>A checked-out <code>cxcore</code> runtime repository beside <code>cxc</code>, or its path passed with <code>--cxcore-dir</code>.</li><li>The CX source repositories: <a href="https://github.com/cx-pl/cxc" target="_blank" rel="noreferrer">compiler</a>, <a href="https://github.com/cx-pl/cxcore" target="_blank" rel="noreferrer">runtime</a>, and <a href="https://github.com/cx-pl/examples" target="_blank" rel="noreferrer">examples</a>.</li></ul><p>The commands below assume the repositories are siblings in one workspace. The exact compiler and runtime revisions recorded for this documentation are listed on the <a href="/project/revisions.html">tested revisions page</a>. They are development snapshots and may not be suitable together with newer working-tree changes.</p><h2 id="build-the-compiler" tabindex="-1">Build the compiler <a class="header-anchor" href="#build-the-compiler" aria-label="Permalink to &quot;Build the compiler&quot;">​</a></h2><p>From the workspace root:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet build .\\cxc\\src\\CxCompiler.csproj </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">configuration Release</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The compiler DLL is produced under <code>cxc/src/bin/Release/net10.0/</code>. To check the CLI:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet .\\cxc\\src\\bin\\Release\\net10.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\CxCompiler.dll </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet .\\cxc\\src\\bin\\Release\\net10.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\CxCompiler.dll </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">help</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="build-and-run-hello-world" tabindex="-1">Build and run Hello World <a class="header-anchor" href="#build-and-run-hello-world" aria-label="Permalink to &quot;Build and run Hello World&quot;">​</a></h2><p>Run the compiler from the workspace root:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet .\\cxc\\src\\bin\\Release\\net10.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\\CxCompiler.dll </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">compile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cxcore</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dir .\\cxcore </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.\\examples\\0. Hello World\\HelloWorld.cx&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The executable is emitted under the example&#39;s <code>.bin/</code> directory. Run the matching executable for your configuration and platform. On Windows Release, for example:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.\\examples\\0. Hello World\\.bin\\Release\\HelloWorld.exe&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Expected output:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello world!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>--compile</code> asks CMake to compile generated C. Without it, the compiler emits generated files only. The <code>.obj/</code> directory holds generated sources and build files; <code>.bin/</code> holds built executables and libraries.</p><h2 id="platform-notes" tabindex="-1">Platform notes <a class="header-anchor" href="#platform-notes" aria-label="Permalink to &quot;Platform notes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>What the repositories document</th><th>Notes</th></tr></thead><tbody><tr><td>Windows x64</td><td>MSVC and CMake builds; the VS Code extension documents build, run, and debugging</td><td>Install Visual Studio C++ build tools and CMake. This guide&#39;s output path assumes the default Release configuration.</td></tr><tr><td>Linux x64</td><td>GCC and CMake runtime build</td><td>The runtime README recommends its Linux development container. Confirm the compiler and runtime revisions match.</td></tr></tbody></table><p>These are repository-supported development paths, not a guarantee that every feature has identical support. Other operating systems, architectures, and toolchains may be incomplete.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>If the compiler cannot locate the runtime, pass its path explicitly with <code>--cxcore-dir</code>.</li><li>If the compiler emits C and CMake files but no executable, check that CMake and a native C compiler are installed and available on <code>PATH</code>.</li><li>Use <code>--verbosity verbose</code> for additional compiler and build diagnostics.</li><li>See the <a href="/tools/compiler.html">compiler guide</a> and the <a href="https://github.com/cx-pl/cxcore" target="_blank" rel="noreferrer">runtime repository</a> for current setup notes.</li></ul>`,23)])])}const m=i(l,[["render",r]]);export{u as __pageData,m as default};
